'use strict';
let me=null,csrf='',departments=[],clinicians=[],dependants=[],idleTimer=null;
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const initialAuthMarkup=$('#auth').innerHTML;

function stopIdleTimer(){if(idleTimer)clearTimeout(idleTimer);idleTimer=null}
function resetIdleTimer(){if(!me)return;stopIdleTimer();idleTimer=setTimeout(async()=>{try{await fetch('/api/auth/logout',{method:'POST',headers:{'x-csrf-token':csrf}})}catch{}me=null;try{csrf=(await req('/csrf')).token}catch{}$('#headerNotifications')?.classList.add('hidden');showAuth('login');toast('You were signed out after five minutes of inactivity. Please sign in again.');},5*60*1000)}
['pointerdown','keydown','mousemove','touchstart','scroll'].forEach(event=>window.addEventListener(event,resetIdleTimer,{passive:true}));

const toast=(msg,ok=false)=>{const e=$('#toast');e.textContent=msg;e.className='alert'+(ok?' success':'');window.scrollTo({top:0,behavior:'smooth'})};
const req=async(url,method='GET',data)=>{const opts={method,headers:{}};if(method!=='GET'){opts.headers['x-csrf-token']=csrf;if(data instanceof FormData)opts.body=data;else{opts.headers['content-type']='application/json';opts.body=JSON.stringify(data||{})}}const r=await fetch('/api'+url,opts);const out=await r.json();if(!r.ok)throw Error(out.error||'Request failed');return out};
const form=f=>Object.fromEntries(new FormData(f).entries());
const dateSQL=v=>v? v.replace('T',' ')+':00':'';
const tbl=(rows,cols)=>'<div class="tablewrap"><table><thead><tr>'+cols.map(c=>'<th>'+esc(c[0])+'</th>').join('')+'</tr></thead><tbody>'+rows.map(r=>'<tr>'+cols.map(c=>'<td>'+ (typeof c[1]==='function'?c[1](r):esc(r[c[1]]))+'</td>').join('')+'</tr>').join('')+'</tbody></table></div>';
const photo=(id,name)=>id?`<img class="profile-thumb" loading="lazy" src="/api/images/${encodeURIComponent(id)}" alt="Profile photo of ${esc(name)}">`:'<span class="profile-placeholder" aria-label="No profile photo">—</span>';
const opts=(items,label='name')=>items.map(x=>`<option value="${esc(x.id)}">${esc(x[label])}</option>`).join('');
const rolesAdmin=['admin','support'];
const employeeRoles=['staff','admin','doctor','consultant','nurse','lab','pharmacy','support','reception','records','it'];
const dependantRoles=['student','staff','admin','doctor','consultant','nurse','lab','pharmacy','support','reception','records','it'];
const genderOptions='<option value="">Select gender</option><option value="female">Female</option><option value="male">Male</option><option value="other">Other</option><option value="prefer_not_to_say">Prefer not to say</option>';
const rankOptions={"doctor": ["House Officer", "Medical Officer", "Senior Medical Officer", "Principal Medical Officer", "Chief Medical Officer"], "consultant": ["Consultant", "Senior Consultant", "Chief Consultant"], "nurse": ["Nursing Officer", "Senior Nursing Officer", "Principal Nursing Officer", "Chief Nursing Officer"], "reception": ["Receptionist", "Senior Receptionist", "Front Desk Supervisor"], "support": ["Support Officer", "Senior Support Officer", "Support Supervisor"], "lab": ["Medical Laboratory Scientist", "Senior Medical Laboratory Scientist", "Principal Medical Laboratory Scientist"], "pharmacy": ["Pharmacist", "Senior Pharmacist", "Principal Pharmacist"], "records": ["Health Records Officer", "Senior Health Records Officer"], "it": ["IT Officer", "Senior IT Officer"], "staff": ["Staff", "Senior Staff", "Principal Staff"], "student": ["Student"], "admin": ["Assistant Administrator", "Super Administrator"]};
const rankSelect=(name='rank')=>`<label>Professional rank<select class="field" name="${name}" required></select></label>`;
function wireRank(form){const role=form.querySelector('[name=role]'),rank=form.querySelector('[name=rank]');if(!role||!rank)return;const refresh=()=>{const current=rank.value;rank.innerHTML='<option value="">Select rank</option>'+(rankOptions[role.value]||['Staff']).map(x=>`<option value="${esc(x)}">${esc(x)}</option>`).join('');if([...rank.options].some(o=>o.value===current))rank.value=current};role.addEventListener('change',refresh);refresh()}

async function boot(){csrf=(await req('/csrf')).token;const s=await req('/auth/me');if(s.user){me=s.user;if(me.must_change_password){showAuth('login');await firstLoginSetup()}else await portal()}else{showAuth('login')}}
function showAuth(which){if(!$('#loginForm'))$('#auth').innerHTML=initialAuthMarkup;document.body.classList.add('auth-mode');document.body.classList.remove('portal-mode');$('#auth').classList.remove('hidden');$('#portal').classList.add('hidden');$('#loginForm').classList.remove('hidden');const reg=$('#registerForm');if(reg)reg.remove();}
$('#loginForm').onsubmit=async e=>{e.preventDefault();try{const d=await req('/auth/login','POST',form(e.target));me=d.user;csrf=d.csrf;if(d.must_change_password){await firstLoginSetup();return;}await portal();toast('Signed in',true)}catch(e){toast(e.message)}};
async function firstLoginSetup(){const qs=await req('/security/questions');$('#auth').innerHTML=`<div class="auth-kicker">FIRST SIGN-IN SECURITY SETUP</div><h1>Secure your account</h1><p>Your temporary password must be replaced before you can use Azman HealthConnect.</p><form id="firstLoginForm" class="space-y-3"><label>New password (minimum 6 characters)<input class="field" type="password" name="password" minlength="6" required></label><label>Confirm new password<input class="field" type="password" name="confirm_password" minlength="6" required></label><label>Choose a security question<select class="field" name="security_question" required>${qs.questions.map(q=>`<option value="${esc(q)}">${esc(q)}</option>`).join('')}</select></label><label>Security answer<input class="field" name="security_answer" required autocomplete="off"></label><button class="primary w-full">Save and continue</button></form>`;$('#firstLoginForm').onsubmit=async e=>{e.preventDefault();try{const result=await req('/auth/first-login-setup','POST',form(e.target));me.must_change_password=false;await portal();toast(result.recovery_code?'Account setup complete. Save your administrator recovery code: '+result.recovery_code:'Account security setup completed',true)}catch(err){toast(err.message)}}}

$('#logout').onclick=async()=>{stopIdleTimer();await req('/auth/logout','POST');me=null;csrf=(await req('/csrf')).token;showAuth('login')};
async function portal(){resetIdleTimer();document.body.classList.remove('auth-mode');document.body.classList.add('portal-mode');try{departments=await req('/departments');clinicians=await req('/clinicians');dependants=dependantRoles.includes(me.role)?await req('/dependants'):[]}catch(e){toast(e.message)}$('#auth').classList.add('hidden');$('#portal').classList.remove('hidden');$('#headerNotifications')?.classList.remove('hidden');await refreshNotificationBadge();
 const nav=[['dashboard','Dashboard'],['appointments','Appointments']];
 if(['student',...employeeRoles].includes(me.role))nav.push(['booking',me.role==='reception'?'Book for patient':'Book appointment']);
 if(dependantRoles.includes(me.role))nav.push(['dependants','My dependants']);
 nav.push(['messages','Messages'],['notifications','Notifications'],['profile','My profile']);
 if(me.role==='reception')nav.push(['frontdesk','Reception desk'],['patients','Patient directory'],['booking','Book for patient'],['contacts','WhatsApp contacts'],['availability','Doctor availability']);
 if(['admin','support','it'].includes(me.role))nav.push(['users','User directory'],['contacts','WhatsApp contacts']);
  if(['admin','support','doctor','consultant'].includes(me.role))nav.push(['availability','Doctor availability']);
  if(['student','staff'].includes(me.role))nav.push(['myrecords','My medical records']);
  if(['doctor','consultant'].includes(me.role))nav.push(['patienthistory','Patient history']);
 if(['admin','it'].includes(me.role))nav.push(['manage','Manage accounts'],['staffing','Create user account'],['audit','Account activity']);
 if(me.role==='support')nav.push(['shifts','Doctor shifts']);
 if(['doctor','consultant'].includes(me.role))nav.push(['contacts','My patient contacts'],['availability','My availability'],['workflow','Clinical workflows']);
 if(['admin','support','reception','nurse','lab','pharmacy'].includes(me.role))nav.push(['workflow','Clinical workflows']);
 if(['admin','support'].includes(me.role))nav.push(['clinicalConsole','Clinical operations']);
 if(['admin','support'].includes(me.role))nav.push(['shifts','Doctor shifts']);
 const accountNumber=me.identifier||me.spn_number||me.registration_number||'Account number not set';
 $('#nav').innerHTML=nav.filter((x,i)=>nav.findIndex(y=>y[0]===x[0])===i).map(x=>`<button class="navbtn" data-view="${x[0]}">${x[1]}</button>`).join('')+`<div class="sidebar-account"><button type="button" class="sidebar-profile" id="sidebarProfile" aria-label="Open my profile">${photo(me.profile_image_id,me.name)}<span class="sidebar-person"><strong>${esc(me.name)}</strong><small>${esc(accountNumber)}</small></span></button><button type="button" class="navbtn sidebar-logout" id="sidebarLogout">Log out</button></div>`;
 $('#nav').querySelectorAll('button[data-view]').forEach(b=>b.onclick=()=>view(b.dataset.view));$('#sidebarProfile').onclick=()=>view('profile');$('#sidebarLogout').onclick=()=>$('#logout').click();
 $('#mobileMenu').onclick=()=>{const open=$('#nav').classList.toggle('mobile-open');$('#mobileMenu').classList.toggle('is-open',open);$('#mobileMenu').setAttribute('aria-expanded',String(open));$('#mobileMenu').setAttribute('aria-label',open?'Close navigation menu':'Open navigation menu')};view('dashboard')}

async function view(name){if(me)refreshNotificationBadge();if(name==='clinicalConsole'){window.location.href='/clinical-console.html';return;}$('#nav').classList.remove('mobile-open');$('#mobileMenu').classList.remove('is-open');$('#mobileMenu').setAttribute('aria-expanded','false');$('#mobileMenu').setAttribute('aria-label','Open navigation menu');$('#nav').querySelectorAll('button').forEach(b=>b.classList.toggle('active',b.dataset.view===name));try{if(name==='dashboard'&&me.role==='reception'){await receptionistDashboard()}else if(name==='dashboard'&&me.role==='it'){await itDashboard()}else if(name==='dashboard'&&me.role==='support'){await supportDashboard()}else if(name==='dashboard'&&['doctor','consultant'].includes(me.role)){await doctorDashboard()}else if(name==='dashboard'){const rows=await req('/appointments');$('#content').innerHTML=`<h2>Healthcare dashboard</h2><div class="grid"><div class="panel"><h3>Physical clinic visits</h3><p>Book an in-person appointment at the university medical centre.</p><button class="primary" data-go="booking">Book physical visit</button></div><div class="panel"><h3>Online telemedicine</h3><p>Request a remote consultation with an available doctor.</p><button class="primary" data-go="booking">Book online consultation</button></div><div class="panel"><h3>My appointments</h3><p>${rows.length} appointment records available</p><button class="secondary" data-go="appointments">View appointments</button></div></div>`;$('#content').querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>view(b.dataset.go));}
else if(name==='messages')await messagesView();else if(name==='notifications')await notificationsView();else if(name==='profile')await profileView();else if(name==='frontdesk')await receptionistDashboard();else if(name==='patients')await receptionPatientsView();else if(name==='availability')await availabilityView();else if(name==='myrecords')await patientRecordsView();else if(name==='patienthistory')await doctorPatientHistoryView();else if(name==='shifts')await shiftsView();else if(name==='audit')await auditView();else if(name==='booking')await booking();else if(name==='appointments')await appointments();else if(name==='dependants')await dependantsView();else if(name==='users')await usersView();else if(name==='staffing')staffing();else if(name==='contacts')await contactsView();else if(name==='workflow')await workflow();else if(name==='manage')await manageAccounts();}catch(e){toast(e.message)}}
async function booking(selectedPatientId=null){
 const receptionMode=me.role==='reception';const receptionPatients=receptionMode?await req('/reception/patients'):[];
 $('#content').innerHTML=`<h2>${receptionMode?'Book an appointment for a patient':'Book an appointment'}</h2><p>Select a doctor to see only their available 30-minute appointment times. If no times are available, choose another doctor or select any available doctor.</p><form id="bookingForm" class="wide">${receptionMode?`<label>Patient account<select name="patient_id" id="receptionPatient" class="field" required><option value="">Select patient</option>${receptionPatients.map(p=>`<option value="${p.id}" ${String(selectedPatientId)===String(p.id)?'selected':''}>${esc(p.name)} · ${esc(p.identifier)} · ${esc(p.role)}</option>`).join('')}</select></label><label>Dependant<select name="dependant_id" id="receptionDependant" class="field"><option value="">Patient / self</option></select></label>`:''}<label>Consultation mode<select name="mode" class="field" required><option value="physical">Physical / in-person clinic</option><option value="online">Online / telemedicine</option></select></label>${dependantRoles.includes(me.role)&&!receptionMode?`<label>Patient<select name="dependant_id" class="field"><option value="">Myself</option>${dependants.filter(d=>d.status==='approved').map(d=>`<option value="${d.id}">${esc(d.name)} · ${esc(d.dependant_number||'')}</option>`).join('')}</select></label>`:''}<label>Department<select name="department_id" class="field" required>${opts(departments)}</select></label><label>Preferred doctor<select name="clinician_id" id="bookingDoctor" class="field"><option value="">Any available doctor</option>${opts(clinicians)}</select></label><label>Available appointment time<select name="slot" id="bookingSlot" class="field" required><option value="">Choose a doctor to load available times</option></select></label><p id="slotMessage" class="muted">Available appointment times for the next 14 days will appear here.</p><label>Reason for consultation<textarea name="reason" class="field" maxlength="500" required rows="3"></textarea></label><button class="primary">Submit appointment request</button></form>`;
 const doctor=$('#bookingDoctor'),slot=$('#bookingSlot'),message=$('#slotMessage');
 if(receptionMode){const patient=$('#receptionPatient'),dep=$('#receptionDependant');const loadDeps=async()=>{dep.innerHTML='<option value="">Patient / self</option>';if(!patient.value)return;const items=await req('/reception/patients/'+patient.value+'/dependants');dep.innerHTML+=items.map(d=>`<option value="${d.id}">${esc(d.name)} · ${esc(d.dependant_number||'')}</option>`).join('')};patient.onchange=loadDeps;if(patient.value)await loadDeps();}
 const loadSlots=async()=>{slot.innerHTML='<option value="">Loading available times…</option>';message.textContent='Checking the selected doctor’s availability…';try{const url='/availability/slots'+(doctor.value?'?clinician_id='+encodeURIComponent(doctor.value):'');const rows=await req(url);if(!rows.length){slot.innerHTML='<option value="">No available times</option>';message.textContent=doctor.value?'This doctor has no available slots in the next 14 days. Select another doctor or choose Any available doctor.':'No appointment slots are currently published. Please contact reception.';return;}slot.innerHTML='<option value="">Select an available time</option>'+rows.map(r=>`<option value="${r.clinician_id}|${esc(r.starts_at)}">${esc(r.starts_at)} — ${esc(r.clinician)}</option>`).join('');message.textContent=`${rows.length} available appointment slot(s) found. Each appointment is 30 minutes.`;}catch(e){slot.innerHTML='<option value="">Unable to load times</option>';message.textContent=e.message}};
 doctor.onchange=loadSlots;loadSlots();
 $('#bookingForm').onsubmit=async e=>{e.preventDefault();const d=form(e.target);if(!d.slot)return toast('Select an available appointment time');const [clinician_id,starts_at]=d.slot.split('|');d.clinician_id=clinician_id;d.starts_at=starts_at;delete d.slot;if(!d.dependant_id)delete d.dependant_id;if(!d.patient_id)delete d.patient_id;try{const out=await req('/appointments','POST',d);toast(`Appointment #${out.id} submitted. Await confirmation.`,true);view('appointments')}catch(err){toast(err.message);loadSlots()}};
}
async function appointments(){
 const rows=await req('/appointments');const clinician=['doctor','consultant'].includes(me.role),patient=['student','staff'].includes(me.role);
 $('#content').innerHTML='<h2>Appointments</h2><p>Use WhatsApp to coordinate appointment logistics. Keep diagnoses, prescriptions and sensitive medical details inside the secure clinical record.</p>'+tbl(rows,[['Reference','id'],['Patient',r=>esc(r.dependant_name||r.patient_name)],['Department','department_name'],['Mode','mode'],['Doctor',r=>esc(r.clinician_name||'Unassigned')],['Date','starts_at'],['Status','status'],['WhatsApp',r=>r.clinician_id&&['requested','confirmed','checked_in','triage','in_consultation','completed'].includes(r.status)?`<button class="smallbtn" data-wa-appt="${r.id}">${clinician&&Number(r.patient_id)!==Number(me.id)?'Chat patient':(patient||clinician)&&Number(r.patient_id)===Number(me.id)?'Chat doctor':'Chat patient'}</button>`:'—'],['Action',r=>['admin','support','reception','nurse','doctor','consultant'].includes(me.role)?`<button class="smallbtn" data-status="${r.id}">Update</button>`:'—']]);
 $('#content').querySelectorAll('[data-wa-appt]').forEach(b=>b.onclick=async()=>{const popup=window.open('about:blank','_blank');try{const c=await req('/appointments/'+b.dataset.waAppt+'/whatsapp');if(popup)popup.location=c.url;else window.location.href=c.url}catch(e){if(popup)popup.close();toast(e.message)}});
 $('#content').querySelectorAll('[data-status]').forEach(b=>b.onclick=async()=>{const status=prompt('Enter: confirmed, checked_in, triage, in_consultation, completed, cancelled, no_show');if(!status)return;try{await req('/appointments/'+b.dataset.status+'/status','PATCH',{status});view('appointments')}catch(e){toast(e.message)}})
}
async function dependantsView(){
 dependants=await req('/dependants');const available=Math.max(0,3-dependants.filter(d=>d.status==='approved').length);
 $('#content').innerHTML=`<h2>My dependants</h2><p>Add up to three dependants. They become active immediately. You can edit or remove your own dependants at any time.</p>${tbl(dependants.filter(d=>d.status==='approved'),[['Photo',d=>`${photo(d.image_id,d.name)} <input type="file" accept="image/*" data-dep-photo="${d.id}" aria-label="Upload photo for ${esc(d.name)}">`],['Dependant ID','dependant_number'],['Name','name'],['Relationship','relationship'],['Gender','gender'],['Actions',d=>`<button class="smallbtn" data-edit-dep="${d.id}">Edit</button> <button class="secondary" data-delete-dep="${d.id}">Remove</button>`]])}<form id="depForm" class="wide"><div id="depRows"></div><div class="action-grid"><button type="button" class="secondary" id="addDep" ${available?'':'disabled'}>+ Add another</button><button class="primary" ${available?'':'disabled'}>Submit dependants</button></div><p class="muted">${available} dependant slot(s) available. Spouse ID ends /01; children use /02 and /03.</p></form>`;
 const container=$('#depRows');let count=0;const add=()=>{if(count>=available)return;const i=count++;const div=document.createElement('div');div.className='panel';div.innerHTML=`<h3>Dependant ${i+1}</h3><label>Full name<input class="field" name="name${i}" required></label><label>Relationship<select class="field" name="relationship${i}"><option value="spouse">Spouse</option><option value="son">Son</option><option value="daughter">Daughter</option></select></label><label>Date of birth<input class="field" type="date" name="birth_date${i}"></label><label>Gender<select class="field" name="gender${i}">${genderOptions}</select></label><label>Phone<input class="field" name="phone${i}"></label>`;container.appendChild(div);if(count>=available)$('#addDep').disabled=true};$('#addDep').onclick=add;if(available)add();
 $('#depForm').onsubmit=async e=>{e.preventDefault();const data=form(e.target),items=Array.from({length:count},(_,i)=>({name:data['name'+i],relationship:data['relationship'+i],birth_date:data['birth_date'+i],gender:data['gender'+i],phone:data['phone'+i]}));try{const out=await req('/dependants','POST',{dependants:items});toast('Dependants added: '+out.dependants.map(d=>d.dependant_number).join(', '),true);view('dependants')}catch(err){toast(err.message)}};
 $('#content').querySelectorAll('[data-edit-dep]').forEach(b=>b.onclick=async()=>{const d=dependants.find(x=>String(x.id)===b.dataset.editDep);const name=prompt('Dependant full name',d.name);if(name===null)return;const relationship=prompt('Relationship: spouse, son, daughter or other',d.relationship);if(relationship===null)return;const birth_date=prompt('Date of birth (YYYY-MM-DD)',d.birth_date||'');if(birth_date===null)return;const gender=prompt('Gender: female, male, other, prefer_not_to_say',d.gender||'');if(gender===null)return;const phone=prompt('Phone number',d.phone||'');if(phone===null)return;try{await req('/dependants/'+d.id,'PATCH',{name,relationship,birth_date,gender,phone});toast('Dependant updated',true);view('dependants')}catch(e){toast(e.message)}});
 $('#content').querySelectorAll('[data-delete-dep]').forEach(b=>b.onclick=async()=>{const d=dependants.find(x=>String(x.id)===b.dataset.deleteDep);if(!confirm(`Remove ${d.name} from your active dependants? Their past medical records will be retained.`))return;try{await req('/dependants/'+d.id,'DELETE');toast('Dependant removed',true);view('dependants')}catch(e){toast(e.message)}});
 $('#content').querySelectorAll('[data-dep-photo]').forEach(el=>el.onchange=async()=>{if(!el.files[0])return;const fd=new FormData();fd.append('image',el.files[0]);try{await req('/dependants/'+el.dataset.depPhoto+'/profile-image','POST',fd);toast('Photo uploaded',true)}catch(e){toast(e.message)}});
}
async function refreshNotificationBadge(){try{const rows=await req('/app-notifications');const unread=rows.filter(x=>!x.read_at).length;const btn=$('#headerNotifications'),count=$('#headerNotificationCount');if(btn){btn.classList.remove('hidden');btn.onclick=()=>view('notifications');if(count){count.textContent=unread>99?'99+':String(unread);count.classList.toggle('hidden',!unread);}}}catch(e){}}
async function notificationsView(){const rows=await req('/app-notifications');$('#content').innerHTML=`<div class="flex flex-wrap justify-between items-center gap-3"><div><h2>Notifications</h2><p class="muted">Information and updates related to your account, appointments and messages.</p></div><div class="flex gap-2"><button class="secondary" id="readAllNotices">Mark all as read</button><button class="secondary" id="clearNotices">Clear notifications</button></div></div>${rows.length?rows.map(n=>`<article class="panel notice-card ${n.read_at?'':'notice-unread'}"><div class="flex justify-between gap-3"><strong>${esc(n.title)}</strong><small>${esc(n.created_at)}</small></div><p>${esc(n.body)}</p><div class="flex gap-2">${n.target_url?`<button class="smallbtn" data-notice-open="${n.id}" data-target="${esc(n.target_url)}">Open</button>`:''}${!n.read_at?`<button class="secondary" data-notice-read="${n.id}">Mark read</button>`:''}</div></article>`).join(''):'<p class="muted">You have no notifications.</p>'}`;
 $('#readAllNotices').onclick=async()=>{await req('/app-notifications/read-all','POST',{});notificationsView();refreshNotificationBadge()};$('#clearNotices').onclick=async()=>{if(!confirm('Clear all notifications from your view?'))return;await req('/app-notifications','DELETE');notificationsView();refreshNotificationBadge()};$('#content').querySelectorAll('[data-notice-read]').forEach(b=>b.onclick=async()=>{await req('/app-notifications/'+b.dataset.noticeRead+'/read','PATCH',{});notificationsView();refreshNotificationBadge()});$('#content').querySelectorAll('[data-notice-open]').forEach(b=>b.onclick=async()=>{await req('/app-notifications/'+b.dataset.noticeOpen+'/read','PATCH',{});const target=b.dataset.target;if(target==='/messages')view('messages');else if(target==='/appointments')view('appointments');else view('dashboard');refreshNotificationBadge()});}
async function messagesView(){const contacts=await req('/messages/contacts'),conversations=await req('/messages/conversations');$('#content').innerHTML=`<h2>Messages</h2><p class="muted">Secure in-app messages. Patients and university users can contact doctors directly. Doctors can reply to patients assigned to their appointments. IT Support, Support and administrators can communicate with all portal users.</p><div class="grid"><section class="panel"><div class="flex justify-between items-center gap-2"><h3>Start a conversation</h3><button class="secondary" id="clearAllChats">Clear all chats</button></div><label>Choose recipient<select class="field" id="messageRecipient"><option value="">Select a user</option>${contacts.map(c=>`<option value="${c.id}">${esc(c.name)} · ${esc(c.role)}</option>`).join('')}</select></label><button class="primary" id="startConversation">Open chat</button><h3 class="mt-4">Your conversations</h3><div id="conversationList">${conversations.map(c=>`<button class="secondary w-full text-left mb-2" data-conversation="${c.id}"><strong>${esc(c.other_name)}</strong><br><small>${esc(c.other_role)} · ${esc(c.last_message||'No messages yet')}</small>${Number(c.unread_count)?` <b>(${c.unread_count} new)</b>`:''}</button>`).join('')||'<p class="muted">No conversations yet.</p>'}</div></section><section class="panel" id="chatPanel"><h3>Select a conversation</h3><p class="muted">Your messages will appear here.</p></section></div>`;
 $('#clearAllChats').onclick=async()=>{if(!confirm('Clear all conversations from your view? Other participants will retain their copies.'))return;try{await req('/messages/conversations','DELETE');messagesView();toast('All conversations cleared from your view',true)}catch(e){toast(e.message)}};$('#startConversation').onclick=async()=>{const id=$('#messageRecipient').value;if(!id)return toast('Select a recipient');try{const c=await req('/messages/conversations','POST',{user_id:Number(id)});await openConversation(c.id)}catch(e){toast(e.message)}};$('#content').querySelectorAll('[data-conversation]').forEach(b=>b.onclick=()=>openConversation(b.dataset.conversation));}
async function openConversation(id){const data=await req('/messages/conversations/'+id),panel=$('#chatPanel');panel.innerHTML=`<div class="flex justify-between items-center gap-2"><div><h3>${esc(data.conversation.other.name)}</h3><small>${esc(data.conversation.other.role)}</small></div><button class="secondary" id="clearChat">Clear messages</button></div><div class="chat-messages" id="chatMessages">${data.messages.map(m=>`<div class="chat-bubble ${Number(m.sender_id)===Number(me.id)?'chat-mine':'chat-theirs'}"><small>${esc(m.sender_name)} · ${esc(m.created_at)}</small><p>${esc(m.body)}</p></div>`).join('')||'<p class="muted">No messages yet. Start the conversation below.</p>'}</div><form id="sendMessage" class="mt-3"><label>Message<textarea class="field" name="body" rows="3" maxlength="4000" required></textarea></label><button class="primary">Send message</button></form>`;
 $('#clearChat').onclick=async()=>{if(!confirm('Clear this conversation from your view? The other participant will retain their messages.'))return;try{await req('/messages/conversations/'+id,'DELETE');toast('Messages cleared from your view',true);messagesView()}catch(e){toast(e.message)}};$('#sendMessage').onsubmit=async e=>{e.preventDefault();const body=new FormData(e.target).get('body');try{await req('/messages/conversations/'+id,'POST',{body});await openConversation(id);await refreshNotificationBadge()}catch(err){toast(err.message)}};}
async function manageAccounts(){
 const rows=await req('/users');const canEdit=['admin','it'].includes(me.role);
 const roleChoices=['student','staff','doctor','consultant','nurse','lab','pharmacy','support','reception','records','it',...(me.admin_level==='super'?['admin']:[])];
 const protectedAccount=u=>(me.role==='it'&&u.role==='admin')||(u.role==='admin'&&u.admin_level==='super')||(u.role==='admin'&&me.admin_level!=='super');
 $('#content').innerHTML=`<h2>User management</h2><p>Manage user profiles, account status and access. Deleting a user deactivates sign-in while preserving appointments and clinical records. Password recovery remains a separate security function.</p>`+tbl(rows,[['Photo',u=>photo(u.profile_image_id,u.name)],['Name','name'],['Role','role'],['Identifier','identifier'],['Email','email'],['Status',u=>protectedAccount(u)?esc(u.status):`<select class="field" data-account-status="${u.id}">${['pending','approved','rejected','suspended'].map(x=>`<option value="${x}" ${u.status===x?'selected':''}>${x.replace('_',' ')}</option>`).join('')}</select>`],['Actions',u=>canEdit&&!protectedAccount(u)?`<button class="smallbtn" data-account-edit="${u.id}">Edit user</button> <button class="secondary" data-account-save="${u.id}">Save status</button> <button class="secondary" data-account-delete="${u.id}">Delete user</button>`:'Protected account']]);
 $('#content').insertAdjacentHTML('beforeend',`<h3>Create account</h3><form id="newUserForm" class="wide"><label>Name<input name="name" class="field" required></label><label>Email<input name="email" type="email" class="field" required></label><label>SPN / registration number<input name="identifier" class="field" required></label><label>Phone / WhatsApp<input name="phone" class="field"></label><label>Department<input name="department" class="field"></label><label>Gender<select name="gender" class="field" required>${genderOptions}</select></label><label>Account type<select name="role" class="field">${roleChoices.map(x=>`<option value="${x}">${x}</option>`).join('')}</select></label>${rankSelect()}<p class="muted">New accounts receive the system's temporary first-login password and must complete the security setup.</p><button class="primary">Create account</button></form>`);
 wireRank($('#newUserForm'));$('#newUserForm').onsubmit=async e=>{e.preventDefault();try{const out=await req('/admin/users','POST',form(e.target));toast(`Account created. Temporary password: ${out.temporary_password}`,true);view('manage')}catch(err){toast(err.message)}};
 $('#content').querySelectorAll('[data-account-edit]').forEach(b=>b.onclick=async()=>{const u=rows.find(x=>String(x.id)===b.dataset.accountEdit);const name=prompt('Full name',u.name);if(name===null)return;const email=prompt('Email',u.email);if(email===null)return;const identifier=prompt('SPN / registration number',u.identifier||'');if(identifier===null)return;const phone=prompt('Phone / WhatsApp',u.phone||'');if(phone===null)return;const department=prompt('Department',u.department||'');if(department===null)return;try{await req('/admin/users/'+u.id,'PATCH',{...u,name,email,identifier,phone,department});toast('User details updated',true);view('manage')}catch(e){toast(e.message)}});
 $('#content').querySelectorAll('[data-account-save]').forEach(b=>b.onclick=async()=>{const status=$(`[data-account-status="${b.dataset.accountSave}"]`)?.value;if(!status)return;try{await req('/users/'+b.dataset.accountSave+'/status','PATCH',{status});toast('Account status updated',true);view('manage')}catch(e){toast(e.message)}});
 $('#content').querySelectorAll('[data-account-delete]').forEach(b=>b.onclick=async()=>{const u=rows.find(x=>String(x.id)===b.dataset.accountDelete);if(!confirm(`Delete ${u.name}'s account? Their sign-in will be disabled, while appointments and clinical records will be retained.`))return;try{const out=await req('/admin/users/'+u.id,'DELETE');toast(out.message||'User account deactivated',true);view('manage')}catch(e){toast(e.message)}});
}
