async function availabilityView(){
 const isClinician=['doctor','consultant'].includes(me.role),canManage=['admin','support'].includes(me.role);
 const rows=await req('/availability');
 const formHtml=(isClinician||canManage)?`<form id="availabilityForm" class="wide availability-form"><h3>${canManage?'Set doctor availability':'Set my availability'}</h3>${canManage?`<label>Doctor / consultant<select class="field" name="clinician_id" required><option value="">Select clinician</option>${opts(clinicians)}</select></label>`:''}<label>Available date<input class="field" type="date" name="available_date" required></label><div class="availability-time-grid"><label>From<input class="field" type="time" name="from_time" required></label><label>To<input class="field" type="time" name="to_time" required></label></div><p class="muted">Choose any date and time range. Add separate ranges on the same date when needed.</p><button class="primary"><span aria-hidden="true">＋</span> Add availability range</button></form>`:'';
 const action=(r)=>((canManage||isClinician&&Number(r.clinician_id)===Number(me.id))?`<button class="smallbtn" data-edit-availability="${r.id}" title="Edit availability" aria-label="Edit availability">✎</button> <button class="smallbtn danger" data-delete-availability="${r.id}" title="Delete availability" aria-label="Delete availability">🗑</button>`:'—');
 $('#content').innerHTML=`<h2>${isClinician?'My availability':canManage?'Manage doctor availability':'Doctor availability'}</h2><p>Select the specific date and the time range during which the doctor can receive appointments. There are no fixed working hours. You can add more than one time range for a date.</p>${formHtml}`+tbl(rows,[['Doctor','clinician'],['Date','starts_at'],['From',r=>String(r.starts_at).slice(11,16)],['To',r=>String(r.ends_at).slice(11,16)],['Actions',action]]);
 if($('#availabilityForm'))$('#availabilityForm').onsubmit=async e=>{e.preventDefault();const d=form(e.target);if(d.to_time<=d.from_time){toast('The ending time must be later than the starting time.');return;}try{await req('/availability','POST',{clinician_id:d.clinician_id||undefined,starts_at:d.available_date+' '+d.from_time+':00',ends_at:d.available_date+' '+d.to_time+':00'});toast('Availability range added',true);availabilityView()}catch(err){toast(err.message)}};
 $('#content').querySelectorAll('[data-edit-availability]').forEach(b=>b.onclick=async()=>{const row=rows.find(x=>String(x.id)===b.dataset.editAvailability);const date=String(row.starts_at).slice(0,10),from=String(row.starts_at).slice(11,16),to=String(row.ends_at).slice(11,16);const newDate=prompt('Available date (YYYY-MM-DD)',date);if(!newDate)return;const newFrom=prompt('Available from (HH:MM)',from);if(!newFrom)return;const newTo=prompt('Available until (HH:MM)',to);if(!newTo)return;if(newTo<=newFrom){toast('The ending time must be later than the starting time.');return;}let clinician_id=row.clinician_id;if(canManage){const choice=prompt('Doctor user ID (leave unchanged or enter another approved doctor ID)',String(row.clinician_id));if(choice)clinician_id=choice;}try{await req('/availability/'+row.id,'PATCH',{starts_at:newDate+' '+newFrom+':00',ends_at:newDate+' '+newTo+':00',clinician_id});toast('Availability updated',true);availabilityView()}catch(err){toast(err.message)}});
 $('#content').querySelectorAll('[data-delete-availability]').forEach(b=>b.onclick=async()=>{if(!confirm('Delete this availability range? Existing bookings prevent deletion.'))return;try{await req('/availability/'+b.dataset.deleteAvailability,'DELETE');toast('Availability deleted',true);availabilityView()}catch(err){toast(err.message)}});
}
