async function patientRecordsView(){
 const [labs,prescriptions]=await Promise.all([req('/labs'),req('/prescriptions')]);
 $('#content').innerHTML='<h2>My medical records and documents</h2><p>Download prescriptions and laboratory requests. Upload your test result as a PDF, JPG or PNG file (maximum 10 MB) against the relevant laboratory request.</p><h3>Prescriptions</h3>'+tbl(prescriptions,[['Medicine','medication'],['Dose','dose'],['Frequency','frequency'],['Duration','duration'],['Status','status'],['Download',r=>`<a class="smallbtn" href="/api/prescriptions/${r.id}/download.pdf" target="_blank" rel="noopener">Download prescription</a>`]])+'<h3>Laboratory requests</h3>'+tbl(labs,[['Test','test_name'],['Status','status'],['Date','created_at'],['Request paper',r=>`<a class="smallbtn" href="/api/labs/${r.id}/request.pdf" target="_blank" rel="noopener">Download test request</a>`],['Upload result',r=>`<form class="lab-upload" data-lab-upload="${r.id}"><input type="file" name="result_file" accept=".pdf,image/jpeg,image/png,application/pdf" required><button class="smallbtn">Upload</button></form>`]])+'<p class="muted">Uploaded results are attached to the laboratory request for review by the healthcare team.</p>';
 $('#content').querySelectorAll('[data-lab-upload]').forEach(f=>f.onsubmit=async e=>{e.preventDefault();const fd=new FormData(f);try{await req('/labs/'+f.dataset.labUpload+'/upload-result','POST',fd);toast('Test result uploaded',true);patientRecordsView()}catch(err){toast(err.message)}});
}
async function doctorPatientHistoryView(){
 const patients=await req('/doctor/patients');
 $('#content').innerHTML='<h2>Assigned patient history</h2><p>View longitudinal history only for patients with appointments assigned to you.</p>'+tbl(patients,[['Patient','name'],['Identifier','identifier'],['Last visit','last_visit'],['Visits','visit_count'],['History',r=>`<button class="smallbtn" data-patient-history="${r.id}">View history</button>`]]);
 $('#content').querySelectorAll('[data-patient-history]').forEach(b=>b.onclick=async()=>{try{const h=await req('/doctor/patients/'+b.dataset.patientHistory+'/history');const c=$('#content');c.innerHTML=`<button class="secondary" id="backHistory">Back to patients</button><h2>${esc(h.patient.name)} — Patient history</h2><h3>Appointments</h3>${tbl(h.appointments,[['Date','starts_at'],['Mode','mode'],['Status','status'],['Reason','reason']])}<h3>Consultation notes</h3>${tbl(h.encounters,[['Date','created_at'],['Assessment','assessment'],['Plan','plan'],['Signed','signed_at']])}<h3>Vitals</h3>${tbl(h.vitals,[['Date','created_at'],['Temperature','temperature'],['Blood pressure',r=>esc((r.systolic||'—')+'/'+(r.diastolic||'—'))],['Pulse','pulse'],['Oxygen','oxygen'],['Weight','weight']])}<h3>Laboratory tests</h3>${tbl(h.labs,[['Test','test_name'],['Status','status'],['Result','result_text'],['Request paper',r=>`<a class="smallbtn" href="/api/labs/${r.id}/request.pdf" target="_blank">Download</a>`]])}<h3>Prescriptions</h3>${tbl(h.prescriptions,[['Medicine','medication'],['Dose','dose'],['Frequency','frequency'],['Duration','duration'],['PDF',r=>`<a class="smallbtn" href="/api/prescriptions/${r.id}/download.pdf" target="_blank">Download</a>`]])}`;$('#backHistory').onclick=doctorPatientHistoryView}catch(err){toast(err.message)}});
}
async function workflow(){let html='<h2>Clinical workflow</h2><p>Choose a queue. Medical records require authorization and clinician assignment.</p><div class="grid">';if(['admin','nurse','doctor','consultant'].includes(me.role))html+='<button class="secondary" data-clin="vitals">Nursing vitals</button>';if(['doctor','consultant'].includes(me.role))html+='<button class="secondary" data-clin="notes">Consultation notes</button><button class="secondary" data-clin="order">Order laboratory test</button><button class="secondary" data-clin="prescribe">Prescribe medication</button>';if(['admin','lab','doctor','consultant'].includes(me.role))html+='<button class="secondary" data-clin="labs">Laboratory queue</button>';if(['admin','pharmacy','doctor','consultant'].includes(me.role))html+='<button class="secondary" data-clin="rx">Prescription queue</button>';html+='</div><div id="workarea"></div>';$('#content').innerHTML=html;$('#content').querySelectorAll('[data-clin]').forEach(b=>b.onclick=()=>clinical(b.dataset.clin))}
async function clinical(type){const a=$('#workarea');if(type==='labs'){const rows=await req('/labs');a.innerHTML=tbl(rows,[['ID','id'],['Appointment','appointment_id'],['Test','test_name'],['Status','status'],['Result','result_text'],['Action',r=>me.role==='lab'?`<button class="smallbtn" data-lab="${r.id}">Update</button>`:'—']]);a.querySelectorAll('[data-lab]').forEach(b=>b.onclick=async()=>{const status=prompt('Status: collected, processing, released');if(!status)return;const result_text=status==='released'?prompt('Result text (required)'):'';try{await req('/labs/'+b.dataset.lab,'PATCH',{status,result_text});clinical('labs')}catch(e){toast(e.message)}});return}if(type==='rx'){const rows=await req('/prescriptions');a.innerHTML=tbl(rows,[['ID','id'],['Appointment','appointment_id'],['Medicine','medication'],['Dose','dose'],['Status','status'],['Action',r=>me.role==='pharmacy'&&r.status==='ordered'?`<button class="smallbtn" data-rx="${r.id}">Dispense</button>`:'—']]);a.querySelectorAll('[data-rx]').forEach(b=>b.onclick=async()=>{try{await req('/prescriptions/'+b.dataset.rx+'/dispense','PATCH');clinical('rx')}catch(e){toast(e.message)}});return}const fields={vitals:[['temperature','Temperature °C'],['systolic','Systolic BP'],['diastolic','Diastolic BP'],['pulse','Pulse'],['oxygen','Oxygen saturation'],['weight','Weight kg'],['notes','Notes']],notes:[['subjective','Subjective'],['objective','Objective'],['assessment','Assessment'],['plan','Plan']],order:[['test_name','Test name']],prescribe:[['medication','Medication'],['dose','Dose'],['route','Route'],['frequency','Frequency'],['duration','Duration'],['instructions','Instructions']]};a.innerHTML=`<h3>${esc(type)}</h3><form id="clinicalForm" class="wide"><label>Appointment ID<input name="appointment_id" class="field" required type="number" min="1"></label>${fields[type].map(([n,l])=>`<label>${l}<input name="${n}" class="field"></label>`).join('')}<button class="primary">Save</button></form>`;$('#clinicalForm').onsubmit=async e=>{e.preventDefault();const d=form(e.target);try{if(type==='notes'){await req('/encounters/'+d.appointment_id,'POST',d)}else await req('/'+({vitals:'vitals',order:'labs',prescribe:'prescriptions'}[type]),'POST',d);toast('Clinical entry saved',true)}catch(err){toast(err.message)}}}
boot().catch(e=>toast(e.message));

// Security question options are centrally defined by the backend.
(async()=>{try{const response=await fetch('/api/security/questions');if(!response.ok)return;const data=await response.json();const select=document.getElementById('securityQuestion');if(select){select.innerHTML='<option value="">Select a security question</option>';window.azmanSecurityQuestions=data.questions;for(const question of data.questions){const option=document.createElement('option');option.value=question;option.textContent=question;select.appendChild(option)}}}catch(e){console.warn('Security questions unavailable')}})();

async function contactsView(){
 const rows=await req('/whatsapp/contacts');$('#content').innerHTML='<h2>WhatsApp contacts</h2><p>Reception can contact approved portal users and registered dependants using their saved WhatsApp numbers. Keep sensitive medical information inside HealthConnect. WhatsApp opens the registered number without API credentials. Keep sensitive medical information in HealthConnect.</p>'+tbl(rows,[['Name','name'],['Role / relationship',r=>esc(r.role==='dependant'?'Dependant':r.role)],['Identifier','identifier'],['Phone','phone'],['Linked staff',r=>esc(r.owner_name||'—')],['Action',r=>`<button class="smallbtn" data-wa-type="${r.contact_type}" data-wa-id="${r.id}">Open WhatsApp</button>`]]);
 $('#content').querySelectorAll('[data-wa-id]').forEach(b=>b.onclick=async()=>{const popup=window.open('about:blank','_blank');try{const endpoint=b.dataset.waType==='dependant'?'/whatsapp/dependant/':'/whatsapp/contact/';const d=await req(endpoint+b.dataset.waId);if(popup)popup.location=d.url;else window.location.href=d.url}catch(e){if(popup)popup.close();toast(e.message)}})
}

async function profileView(){const d=await req('/auth/me');me=d.user;$('#content').innerHTML=`<h2>My profile</h2><div class="panel">${photo(me.profile_image_id,me.name)} <strong>${esc(me.name)}</strong><p>${esc(me.role)}</p><form id="profileUpload"><label>Upload or replace profile picture<input class="field" type="file" accept="image/jpeg,image/png,image/webp" name="image" required></label><button class="primary">Save profile picture</button></form></div>`;$('#profileUpload').onsubmit=async e=>{e.preventDefault();try{const fd=new FormData(e.target);await req('/images/profile','POST',fd);const d=await req('/auth/me');me=d.user;toast('Profile picture saved',true);profileView()}catch(err){toast(err.message)}}}
